package serverviwe.view.controller;
import jakarta.servlet.http.HttpSession; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import serverviwe.view.service.AuditService; import serverviwe.view.service.ServiceMonitor;
@Controller @RequiredArgsConstructor public class ServiceController { private final ServiceMonitor monitor; private final AuditService audit;
@GetMapping("/service-monitor") public String page(HttpSession s,Model m){try{if(s.getAttribute("host")==null)return "redirect:/connecttovps";var serviceMap=monitor.getServices((String)s.getAttribute("host"),(Integer)s.getAttribute("port"),(String)s.getAttribute("username"),(String)s.getAttribute("password")); m.addAllAttributes(serviceMap); m.addAttribute("services",serviceMap);}catch(Exception e){m.addAttribute("error",e.getMessage());}return "service-monitor";}
@PostMapping("/service-monitor/action") public String action(@RequestParam String service,@RequestParam String action,HttpSession s,Model m){try{String out=monitor.action((String)s.getAttribute("host"),(Integer)s.getAttribute("port"),(String)s.getAttribute("username"),(String)s.getAttribute("password"),service,action);audit.log("SERVICE_"+action.toUpperCase(),(String)s.getAttribute("host"),(String)s.getAttribute("username"),service+" -> "+out);m.addAttribute("message",out);}catch(Exception e){m.addAttribute("error",e.getMessage());}return page(s,m);}}
